1	package relayproof
2	
3	// Regression coverage for the end-of-input decision when a single Read
4	// delivers bytes together with a COMBINED error: one that carries io.EOF
5	// joined with another independent cause (errors.Join), possibly behind
6	// ordinary %w wrapping. errors.Is(err, io.EOF) matches such a combination,
7	// so it used to be mistaken for a clean end of input: the real read cause
8	// vanished and the newline-less tail fragment was normalized as if it were
9	// a complete final line.
10	//
11	// The fixed contract asserted here:
12	//   - only an error that is io.EOF and nothing else (plain, %w-wrapped, or
13	//     joined with nothing but io.EOF) is normal completion; a combination
14	//     that pairs io.EOF with any other independent cause is a read fault;
15	//   - the caller recognizes the interruption via errors.Is against both
16	//     ErrLogRead and the reader's own cause, and the diagnostic text keeps
17	//     that cause; processing stops without another Read;
18	//   - complete newline-ended lines delivered with the fault are still
19	//     processed in order (valid lines succeed, invalid lines keep their
20	//     original failure reason, blank lines occupy a number without output),
21	//     while the newline-less tail belongs to the failed read: no event, no
22	//     failure record, no count — even when it is itself a fully legal JSON
23	//     object. With no complete line at all the output is empty and the
24	//     failure count zero, yet the return still reports the interruption;
25	//   - the source-CIDR filter only hides success records; it never hides the
26	//     interruption, and a later output fault supplements the diagnostic
27	//     text without replacing or joining the read error chain.
28	//
29	// Everything is scripted in-process, so the boundary reproduces
30	// deterministically offline without real pipes, networks, or devices.
31	
32	import (
33		"bytes"
34		"errors"
35		"fmt"
36		"io"
37		"strings"
38		"testing"
39	)
40	
41	// oneShotFaultReader delivers all of data together with err on the first
42	// Read, mirroring a reader whose underlying device fails in the same read
43	// that hands over the final bytes. Any later Read is counted: processing
44	// must stop at the fault instead of reading on to confirm the end.
45	type oneShotFaultReader struct {
46		data           []byte
47		err            error
48		delivered      bool
49		postFaultReads int
50	}
51	
52	func (r *oneShotFaultReader) Read(p []byte) (int, error) {
53		if r.delivered {
54			r.postFaultReads++
55			return 0, r.err
56		}
57		r.delivered = true
58		n := copy(p, r.data)
59		if n < len(r.data) {
60			panic("oneShotFaultReader data larger than the caller's buffer; shrink the data")
61		}
62		return n, r.err
63	}
64	
65	// combinedFaultFixture is the shared batch for the combined-error runs:
66	//
67	//	line 1: valid log                                -> success
68	//	line 2: invalid timestamp                        -> failure with reason
69	//	line 3: blank line                               -> no output, keeps number
70	//	line 4: valid log                                -> success
71	//	tail:   valid JSON object WITHOUT a newline      -> part of the failed read
72	//
73	// The tail is a fully legal log on its own, so mistaking the combined error
74	// for a clean EOF is directly observable as a fifth record.
75	func combinedFaultFixture() (complete, tail string) {
76		complete = strings.Join([]string{
77			validLog("a"),
78			`{"timestamp":"not-a-time","action":"b"}`,
79			``,
80			validLog("d"),
81		}, "\n") + "\n"
82		tail = `{"timestamp":"2026-01-02T00:00:00Z","action":"combined-tail"}`
83		return complete, tail
84	}
85	
86	// A combined io.EOF+fault error delivered with the final batch is a read
87	// interruption: the complete lines are processed exactly as in a healthy
88	// run, the legal newline-less tail leaves no trace, the failure count
89	// covers only the invalid complete line, and the returned error keeps both
90	// ErrLogRead and the reader's own cause recognizable — whether the
91	// combination is bare or hidden behind ordinary %w wrapping.
92	func TestNormalizeIOCombinedEOFFaultIsReadInterruption(t *testing.T) {
93		complete, tail := combinedFaultFixture()
94	
95		var healthy bytes.Buffer
96		healthyFailures, healthyErr := NormalizeReader(strings.NewReader(complete), &healthy)
97		if healthyErr != nil || healthyFailures != 1 {
98			t.Fatalf("test setup: healthy reference read failed: failures=%d err=%v", healthyFailures, healthyErr)
99		}
100	
101		cases := []struct {
102			name string
103			err  error
104		}{
105			{"joined EOF and fault", errors.Join(io.EOF, errSimulatedRead)},
106			{"joined fault and EOF (order swapped)", errors.Join(errSimulatedRead, io.EOF)},
107			{"wrapped joined combination", fmt.Errorf("upstream device lost: %w", errors.Join(io.EOF, errSimulatedRead))},
108		}
109		for _, tc := range cases {
110			t.Run(tc.name, func(t *testing.T) {
111				src := &oneShotFaultReader{data: []byte(complete + tail), err: tc.err}
112				var out bytes.Buffer
113				failures, err := NormalizeReader(src, &out)
114				if err == nil {
115					t.Fatalf("a combined EOF+fault error must not be normal completion")
116				}
117				if !errors.Is(err, ErrLogRead) {
118					t.Fatalf("caller must recognize ErrLogRead, got %v", err)
119				}
120				if !errors.Is(err, errSimulatedRead) {
121					t.Fatalf("the reader's own cause must stay reachable through the combination, got %v", err)
122				}
123				if errors.Is(err, ErrLogWrite) {
124					t.Fatalf("a healthy writer must not tag the error as a write failure: %v", err)
125				}
126				if !strings.Contains(err.Error(), errSimulatedRead.Error()) {
127					t.Fatalf("diagnostic text must keep the read cause, got %q", err.Error())
128				}
129				if failures != 1 {
130					t.Fatalf("only the invalid complete line counts; the failed-read tail adds nothing, got %d", failures)
131				}
132				if src.postFaultReads != 0 {
133					t.Fatalf("processing must stop at the fault without reading on, got %d post-fault reads", src.postFaultReads)
134				}
135				if !bytes.Equal(out.Bytes(), healthy.Bytes()) {
136					t.Fatalf("complete lines must be processed exactly as in a healthy run:\nfault:   %q\nhealthy: %q", out.String(), healthy.String())
137				}
138				if bytes.Contains(out.Bytes(), []byte("combined-tail")) {
139					t.Fatalf("the newline-less tail belongs to the failed read and must leave no record: %q", out.String())
140				}
141				results := decodeResults(t, out.Bytes())
142				if len(results) != 3 {
143					t.Fatalf("expected the 3 non-blank complete lines only, got %#v", results)
144				}
145				if results[0]["line"] != float64(1) || results[0]["ok"] != true {
146					t.Fatalf("line 1 must succeed with its physical number: %#v", results[0])
147				}
148				if results[1]["line"] != float64(2) || results[1]["ok"] != false {
149					t.Fatalf("line 2 must keep its physical number past the blank line: %#v", results[1])
150				}
151				if msg, _ := results[1]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
152					t.Fatalf("line 2 must keep its original failure reason, got %q", msg)
153				}
154				if results[2]["line"] != float64(4) || results[2]["ok"] != true {
155					t.Fatalf("line 4 must succeed with its physical number: %#v", results[2])
156				}
157			})
158		}
159	}
160	
161	// The combined fault arrives with only a newline-less fragment and no
162	// complete line at all: the output is empty and the failure count zero, yet
163	// the return value still reports the read interruption.
164	func TestNormalizeIOCombinedEOFFaultWithoutAnyCompleteLine(t *testing.T) {
165		_, tail := combinedFaultFixture()
166		src := &oneShotFaultReader{data: []byte(tail), err: errors.Join(io.EOF, errSimulatedRead)}
167		var out bytes.Buffer
168		failures, err := NormalizeReader(src, &out)
169		if !errors.Is(err, ErrLogRead) || !errors.Is(err, errSimulatedRead) {
170			t.Fatalf("want ErrLogRead wrapping the reader's cause, got %v", err)
171		}
172		if failures != 0 {
173			t.Fatalf("no complete line means no failed logs, got %d", failures)
174		}
175		if out.Len() != 0 {
176			t.Fatalf("no complete line means no output, got %q", out.String())
177		}
178		if src.postFaultReads != 0 {
179			t.Fatalf("processing must stop at the fault without reading on, got %d post-fault reads", src.postFaultReads)
180		}
181	}
182	
183	// Errors that carry io.EOF and NOTHING else stay normal completion: the
184	// plain marker, an ordinary %w chain around it, and a join of only EOF
185	// markers all process the newline-less final line and return no error.
186	func TestNormalizeIOOnlyEOFWrappingsStayCleanCompletion(t *testing.T) {
187		complete, tail := combinedFaultFixture()
188		cases := []struct {
189			name string
190			err  error
191		}{
192			{"plain io.EOF", io.EOF},
193			{"wrapped io.EOF", fmt.Errorf("connection closed: %w", io.EOF)},
194			{"join of only EOF markers", errors.Join(io.EOF, io.EOF)},
195		}
196		for _, tc := range cases {
197			t.Run(tc.name, func(t *testing.T) {
198				src := &scriptReader{steps: []scriptStep{
199					{data: []byte(complete + tail), err: tc.err},
200				}}
201				var out bytes.Buffer
202				failures, err := NormalizeReader(src, &out)
203				if err != nil {
204					t.Fatalf("an error that is only io.EOF must be normal completion, got %v", err)
205				}
206				if failures != 1 {
207					t.Fatalf("only the invalid complete line counts, got %d", failures)
208				}
209				results := decodeResults(t, out.Bytes())
210				if len(results) != 4 {
211					t.Fatalf("the newline-less final line must be processed at a clean EOF: %#v", results)
212				}
213				if results[3]["line"] != float64(5) || results[3]["ok"] != true {
214					t.Fatalf("the tail must become physical line 5: %#v", results[3])
215				}
216				if eventOf(t, results[3])["action"] != "combined-tail" {
217					t.Fatalf("final line content mismatch: %#v", results[3])
218				}
219			})
220		}
221	}
222	
223	// Under the source-CIDR filter the same end decision holds: the filter
224	// hides the out-of-network success but never the read interruption, and the
225	// in-network newline-less tail riding the combined fault leaves no record.
226	func TestNormalizeReaderFilteredCombinedEOFFaultIsReadInterruption(t *testing.T) {
227		f, err := ParseSourceCIDRFilter("192.0.2.0/24")
228		if err != nil {
229			t.Fatal(err)
230		}
231		filter := &f
232		complete := strings.Join([]string{
233			`{"timestamp":"2026-01-02T00:00:00Z","action":"in-allowed","source_ip":"192.0.2.10"}`,
234			`{"timestamp":"2026-01-02T00:00:00Z","action":"out-dropped","source_ip":"198.51.100.20"}`,
235			`{"timestamp":"not-a-time","action":"bad-time-outside","source_ip":"198.51.100.30"}`,
236		}, "\n") + "\n"
237		tail := `{"timestamp":"2026-01-02T00:00:00Z","action":"tail-in-allowed","source_ip":"192.0.2.77"}`
238	
239		src := &oneShotFaultReader{
240			data: []byte(complete + tail),
