	if len(whole) != 1 || whole[0]["line"] != float64(1) || whole[0]["ok"] != false {
		t.Fatalf("only the line-1 failure record may decode whole: %#v", whole)
	}
	if msg, _ := whole[0]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
