package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"strings"

	"github.com/asdhoaiqqq/relayproof-bridge/relayproof"
)

var errUpstream = errors.New("upstream device reset")
var errDisk = errors.New("disk quota exceeded")

// oneShotReader hands back all of data together with err on the first Read.
type oneShotReader struct {
	data []byte
	err  error
}

func (r *oneShotReader) Read(p []byte) (int, error) {
	n := copy(p, r.data)
	if n < len(r.data) {
		panic("enlarge the Read buffer")
	}
	return n, r.err
}

// failingWriter rejects every Write after accepting allowBytes in total.
type failingWriter struct {
	allowBytes int
	got        bytes.Buffer
}

func (w *failingWriter) Write(p []byte) (int, error) {
	remaining := w.allowBytes - w.got.Len()
	if remaining <= 0 {
		return 0, errDisk
	}
	if len(p) <= remaining {
		w.got.Write(p)
		return len(p), nil
	}
	w.got.Write(p[:remaining])
	return remaining, errDisk
}

const (
	good1 = `{"timestamp":"2026-10-04T08:30:00Z","action":"login"}`
	bad2  = `{"timestamp":"not-a-time","action":"deny"}`
	good3 = `{"timestamp":"2026-10-04T09:00:00Z","action":"logout"}` // 末段，不带换行
)

func run(name string, r io.Reader, w io.Writer) {
	failures, err := relayproof.NormalizeReader(r, w)
	fmt.Printf("=== %s ===\n", name)
	fmt.Printf("failures=%d\n", failures)
	if err == nil {
		fmt.Println("err=<nil>")
	} else {
		fmt.Printf("err=%v\n", err)
		fmt.Printf("errors.Is(ErrLogRead)=%v  errors.Is(ErrLogWrite)=%v  errors.Is(errUpstream)=%v  errors.Is(io.EOF)=%v\n",
			errors.Is(err, relayproof.ErrLogRead),
			errors.Is(err, relayproof.ErrLogWrite),
			errors.Is(err, errUpstream),
			errors.Is(err, io.EOF))
	}
	fmt.Println("---- writer 收到的内容 ----")
	return
}

func main() {
	batch := good1 + "\n" + bad2 + "\n" + good3

	// 1) 干净 EOF（末行无换行）
	var out1 bytes.Buffer
	run("正常结束：io.EOF", strings.NewReader(batch), &out1)
	fmt.Print(out1.String())

	// 2) 同批数据，但最后一次 Read 同时返回 EOF 与独立读取故障
	var out2 bytes.Buffer
	run("读取中断：errors.Join(io.EOF, errUpstream)",
		&oneShotReader{data: []byte(batch), err: errors.Join(io.EOF, errUpstream)}, &out2)
	fmt.Print(out2.String())

	// 3) 组合错误外面再包一层
	var out3 bytes.Buffer
	run("读取中断：包装后的组合错误",
		&oneShotReader{data: []byte(batch), err: fmt.Errorf("upstream connection lost: %w", errors.Join(io.EOF, errUpstream))}, &out3)
	fmt.Print(out3.String())

	// 4) 只有未结束片段，没有完整行
	var out4 bytes.Buffer
	run("读取中断：只有未结束片段",
		&oneShotReader{data: []byte(good3), err: errors.Join(io.EOF, errUpstream)}, &out4)
	fmt.Printf("(writer 长度=%d)\n", out4.Len())

	// 5) 读取已故障，随后写出也失败（记录很小，写出失败发生在收尾 Flush）
	w5 := &failingWriter{}
	run("读写同时失败：读故障先到手，Flush 再失败",
		&oneShotReader{data: []byte(batch), err: errors.Join(io.EOF, errUpstream)}, w5)
	fmt.Printf("(writer 长度=%d)\n", w5.got.Len())
}

